/* @autogenerated */
package net.civeira.phylax.feature.oauth.userinvitation.infrastructure.driven;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Optional;

import javax.sql.DataSource;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.crypto.SecretDigester;
import net.civeira.phylax.feature.oauth.userinvitation.domain.InvitationRecord;
import net.civeira.phylax.feature.oauth.userinvitation.domain.gateway.UserInvitationLookupGateway;

/**
 * Reads {@code access_user_invitation} (task 2.2). The link token is looked up by its digest, the
 * same {@link SecretDigester} value the entity stores.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class InvitationLookupAdapter implements UserInvitationLookupGateway {

  static final String COLUMNS = "uid, tenant, email, status, expires_at";

  private final DataSource source;
  private final SecretDigester digester;

  @Override
  public Optional<InvitationRecord> findByToken(String rawToken, String tenantUid) {
    return one(
        "SELECT " + COLUMNS + " FROM access_user_invitation WHERE token_hash = ? AND tenant = ?",
        digester.digest(rawToken), tenantUid);
  }

  @Override
  public Optional<InvitationRecord> findPendingByEmail(String email, String tenantUid) {
    return one("SELECT " + COLUMNS + " FROM access_user_invitation WHERE email = ? AND tenant = ?"
        + " AND status = 'PENDING' ORDER BY created_at DESC LIMIT 1", email, tenantUid);
  }

  private Optional<InvitationRecord> one(String sql, String first, String second) {
    try (Connection conn = source.getConnection();
        PreparedStatement stat = conn.prepareStatement(sql)) {
      stat.setString(1, first);
      stat.setString(2, second);
      try (ResultSet rs = stat.executeQuery()) {
        return rs.next() ? Optional.of(read(rs)) : Optional.empty();
      }
    } catch (SQLException ex) {
      throw new IllegalStateException("Unable to read invitations", ex);
    }
  }

  static InvitationRecord read(ResultSet rs) throws SQLException {
    java.sql.Timestamp expires = rs.getTimestamp("expires_at");
    return new InvitationRecord(rs.getString("uid"), rs.getString("tenant"), rs.getString("email"),
        rs.getString("status"), expires == null ? null : expires.toInstant());
  }
}
